static int tripOnce=0,recoveryWait=0,recoveries=0;
static int done=0,inspected=0,boardCaptured=0;static u64 started=0;static touchPosition queuedTouch;
static struct {int backup,commands,deferred;} restores[4];static unsigned restoreCount=0;
void ilex_test_restored(int backup,int commands,int deferred){if(restoreCount<4){restores[restoreCount].backup=backup;restores[restoreCount].commands=commands;restores[restoreCount++].deferred=deferred;}}
static unsigned bytecodeFiles=0,sourceFiles=0;static size_t bytecodeBytes=0;
void ilex_test_runtime_file(int compiled,size_t bytes){if(compiled){bytecodeFiles++;bytecodeBytes+=bytes;}else sourceFiles++;}
static struct {char name[24];u64 total,max;unsigned calls;} metrics[12];
void ilex_test_record(const char *name,u64 ms){for(unsigned i=0;i<12;i++){if(!metrics[i].name[0])snprintf(metrics[i].name,sizeof(metrics[i].name),"%.23s",name);if(!strcmp(metrics[i].name,name)){metrics[i].total+=ms;if(ms>metrics[i].max)metrics[i].max=ms;metrics[i].calls++;break;}}}
int ilex_test_finished(void){return done;}
static JSValue invoke(JSContext *ctx,const char *name,int argc,JSValueConst *argv){JSValue g=JS_GetGlobalObject(ctx),o=JS_GetPropertyStr(ctx,g,"IlexAutomation"),f=JS_GetPropertyStr(ctx,o,name),v=JS_Call(ctx,f,o,argc,argv);JS_FreeValue(ctx,g);JS_FreeValue(ctx,o);JS_FreeValue(ctx,f);return v;}
static void capture(const char *name,gfxScreen_t screen){char path[160];snprintf(path,sizeof(path),PREFIX "%s",name);FILE *f=fopen(path,"wb");if(!f)return;u16 w,h;u8 *fb=gfxGetFramebuffer(screen,GFX_LEFT,&w,&h);u32 header[4]={0x46584c49,w,h,2};fwrite(header,1,sizeof(header),f);fwrite(fb,1,(size_t)w*h*2,f);fclose(f);}
void ilex_test_capture(const char *name,gfxScreen_t screen){capture(name,screen);}
u32 ilex_test_audio_keys(void){static unsigned n=0;const u32 keys[]={0,KEY_RIGHT,KEY_LEFT,KEY_DOWN,KEY_LEFT,KEY_RIGHT,KEY_DOWN,KEY_A,KEY_A,KEY_B};if(n==9)capture("native-audio.fb",GFX_BOTTOM);return n<10?keys[n++]:KEY_B;}
static void finish(JSContext *ctx,const char *error){if(done)return;done=1;if(!ctx){FILE *f=fopen(PREFIX "native-result.json","wb");if(f){fputs("{\"passed\":false,\"error\":\"Native hardware preflight failed\"}",f);fclose(f);}return;}JSValue result=invoke(ctx,"result",0,NULL);if(JS_IsException(result)){JSValue e=JS_GetException(ctx);JS_FreeValue(ctx,e);JS_FreeValue(ctx,result);result=JS_NewObject(ctx);}JSMemoryUsage usage;JS_ComputeMemoryUsage(JS_GetRuntime(ctx),&usage);JS_SetPropertyStr(ctx,result,"armCompiled",JS_NewBool(ctx,1));JS_SetPropertyStr(ctx,result,"elapsedMs",JS_NewInt64(ctx,osGetTime()-started));JS_SetPropertyStr(ctx,result,"allocatedBytes",JS_NewInt64(ctx,usage.malloc_size));JS_SetPropertyStr(ctx,result,"error",JS_NewString(ctx,error?error:""));if(error&&*error)JS_SetPropertyStr(ctx,result,"passed",JS_NewBool(ctx,0));JS_SetPropertyStr(ctx,result,"audioBackend",JS_NewString(ctx,ilex_audio_status()));JS_SetPropertyStr(ctx,result,"audioEvents",JS_NewUint32(ctx,ilex_audio_test_events()));JS_SetPropertyStr(ctx,result,"recoveryCount",JS_NewInt32(ctx,recoveries));JSValue restoreEvents=JS_NewArray(ctx);for(unsigned i=0;i<restoreCount;i++){JSValue e=JS_NewObject(ctx);JS_SetPropertyStr(ctx,e,"backup",JS_NewBool(ctx,restores[i].backup));JS_SetPropertyStr(ctx,e,"commands",JS_NewInt32(ctx,restores[i].commands));JS_SetPropertyStr(ctx,e,"deferred",JS_NewBool(ctx,restores[i].deferred));JS_SetPropertyUint32(ctx,restoreEvents,i,e);}JS_SetPropertyStr(ctx,result,"restores",restoreEvents);JS_SetPropertyStr(ctx,result,"bytecodeFiles",JS_NewUint32(ctx,bytecodeFiles));JS_SetPropertyStr(ctx,result,"sourceFiles",JS_NewUint32(ctx,sourceFiles));JS_SetPropertyStr(ctx,result,"bytecodeBytes",JS_NewInt64(ctx,bytecodeBytes));JSValue timings=JS_NewObject(ctx);for(unsigned i=0;i<12&&metrics[i].name[0];i++){JSValue metric=JS_NewObject(ctx);JS_SetPropertyStr(ctx,metric,"calls",JS_NewUint32(ctx,metrics[i].calls));JS_SetPropertyStr(ctx,metric,"totalMs",JS_NewInt64(ctx,metrics[i].total));JS_SetPropertyStr(ctx,metric,"maxMs",JS_NewInt64(ctx,metrics[i].max));JS_SetPropertyStr(ctx,timings,metrics[i].name,metric);}JS_SetPropertyStr(ctx,result,"emulatedOperations",timings);JSValue json=JS_JSONStringify(ctx,result,JS_UNDEFINED,JS_UNDEFINED);const char *text=JS_ToCString(ctx,json);FILE *f=fopen(PREFIX "native-result.json","wb");if(f){if(text)fputs(text,f);fclose(f);}JS_FreeCString(ctx,text);JS_FreeValue(ctx,json);JS_FreeValue(ctx,result);capture("native-final-top.fb",GFX_TOP);capture("native-final-bottom.fb",GFX_BOTTOM);}
static JSValue trace(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){(void)self;if(argc){const char *text=JS_ToCString(ctx,argv[0]);FILE *f=fopen(PREFIX "native-trace.txt","ab");if(f){fprintf(f,"%llu %s\n",(unsigned long long)osGetTime(),text?text:"");fclose(f);}JS_FreeCString(ctx,text);}return JS_UNDEFINED;}
static JSValue tripFault(JSContext *ctx,JSValueConst self,int argc,JSValueConst *argv){(void)self;(void)argc;(void)argv;if(tripOnce)return JS_FALSE;tripOnce=1;return JS_TRUE;}
int ilex_test_load(JSContext *ctx){JSValue global=JS_GetGlobalObject(ctx);JS_SetPropertyStr(ctx,global,"IlexTestTripFault",JS_NewCFunction(ctx,tripFault,"IlexTestTripFault",0));JS_SetPropertyStr(ctx,global,"IlexNativeTrace",JS_NewCFunction(ctx,trace,"IlexNativeTrace",1));JS_FreeValue(ctx,global);const char *files[]={"native-test-config.js","native-automation.js"};for(unsigned i=0;i<2;i++){char path[160];snprintf(path,sizeof(path),PREFIX "runtime/%s",files[i]);FILE *f=fopen(path,"rb");if(!f)return 0;fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);char *s=malloc(size+1);if(!s){fclose(f);return 0;}int ok=fread(s,1,size,f)==(size_t)size;fclose(f);s[size]=0;JSValue v=ok?JS_Eval(ctx,s,size,files[i],JS_EVAL_TYPE_GLOBAL):JS_EXCEPTION;free(s);ok=!JS_IsException(v);JS_FreeValue(ctx,v);if(!ok)return 0;}return 1;}
u32 ilex_test_main_keys(unsigned selected,unsigned screen,bool isNew){static unsigned menuFrame=0;if(menuFrame++==0)return 0;if(menuFrame==2){capture("native-home-top.fb",GFX_TOP);capture("native-home-bottom.fb",GFX_BOTTOM);return KEY_SELECT;}if(!started)started=osGetTime();if(!isNew){finish(NULL,"New 3DS required");return KEY_START;}if(done)return KEY_START;if(osGetTime()-started>10800000){finish(NULL,"Test deadline");return KEY_START;}return !screen?(selected==4?KEY_A:KEY_DOWN):0;}
u32 ilex_test_play_keys(JSContext *ctx,JSValueConst view,int boot,int loaded,int inspection,unsigned cursor,int count,unsigned handCursor,int handFocus,const char *error){if(done)return KEY_START;if(!loaded){if(strstr(error,"ILEX_TEST_RECOVERY")&&tripOnce&&!recoveries){if(!recoveryWait++){return 0;}capture("native-error.fb",GFX_BOTTOM);recoveries++;return KEY_A;}finish(ctx,error);return KEY_B;}if(boot){if(error&&*error){finish(ctx,error);return KEY_B;}JSValue g=JS_GetGlobalObject(ctx),cfg=JS_GetPropertyStr(ctx,g,"IlexTestConfig"),mode=JS_GetPropertyStr(ctx,cfg,"resume");int resume=JS_ToBool(ctx,mode);JS_FreeValue(ctx,mode);JS_FreeValue(ctx,cfg);JS_FreeValue(ctx,g);return resume?KEY_X:KEY_A;}if(inspection)return KEY_B;if(JS_IsUndefined(view))return 0;if(osGetTime()-started>10800000){finish(ctx,"Test deadline");return KEY_START;}
 JSValue args[2]={view,JS_NewString(ctx,error)},r=invoke(ctx,"next",2,args);JS_FreeValue(ctx,args[1]);if(JS_IsException(r)){JSValue e=JS_GetException(ctx);const char *s=JS_ToCString(ctx,e);finish(ctx,s?s:"Input planner error");JS_FreeCString(ctx,s);JS_FreeValue(ctx,e);JS_FreeValue(ctx,r);return KEY_START;}JSValue d=JS_GetPropertyStr(ctx,r,"done"),wait=JS_GetPropertyStr(ctx,r,"wait"),back=JS_GetPropertyStr(ctx,r,"back"),row=JS_GetPropertyStr(ctx,r,"row"),inspect=JS_GetPropertyStr(ctx,r,"inspect");JSValue hand=JS_GetPropertyStr(ctx,r,"hand");int32_t handIndex=-1;if(!JS_IsUndefined(hand))JS_ToInt32(ctx,&handIndex,hand);JS_FreeValue(ctx,hand);int inspectCard=JS_ToBool(ctx,inspect);JS_FreeValue(ctx,inspect);int isDone=JS_ToBool(ctx,d),isWait=JS_ToBool(ctx,wait),goBack=JS_ToBool(ctx,back);int32_t index=-1;JS_ToInt32(ctx,&index,row);JS_FreeValue(ctx,d);JS_FreeValue(ctx,wait);JS_FreeValue(ctx,back);JS_FreeValue(ctx,row);JS_FreeValue(ctx,r);if(isDone){finish(ctx,NULL);return KEY_START;}if(isWait)return 0;if(handIndex>=0){if((unsigned)handIndex/7!=handCursor/7)return KEY_RIGHT;queuedTouch.px=16+(handIndex%7)*41+18;queuedTouch.py=ILEX_HAND_Y+25;return KEY_TOUCH;}if(inspectCard)return KEY_X;if(goBack)return KEY_B;if(index<0||index>=count){finish(ctx,"Native input row outside range");return KEY_START;}if((unsigned)index/PAGE != cursor/PAGE)return (unsigned)index<cursor?KEY_L:KEY_R;queuedTouch.px=100;queuedTouch.py=ILEX_CHOICE_Y+(index%PAGE)*ILEX_CHOICE_HEIGHT+8;return KEY_TOUCH;
}
void ilex_test_touch(touchPosition *touch){*touch=queuedTouch;}
void ilex_test_frame(JSContext *ctx,JSValueConst view,int inspection){if(done||!JS_IsObject(view))return;static int setupCaptured=0;JSValue hand=JS_GetPropertyStr(ctx,view,"hand"),hint=JS_IsObject(hand)?JS_GetPropertyStr(ctx,hand,"hint"):JS_UNDEFINED;const char *ht=JS_ToCString(ctx,hint);JSValue automatic=JS_GetPropertyStr(ctx,view,"auto");int isAuto=JS_ToBool(ctx,automatic);JS_FreeValue(ctx,automatic);if(!setupCaptured&&!isAuto&&ht&&strstr(ht,"First selection")){capture("native-setup-hand.fb",GFX_BOTTOM);setupCaptured=1;}JS_FreeCString(ctx,ht);JS_FreeValue(ctx,hint);JS_FreeValue(ctx,hand);if(inspection&&!inspected){capture("native-inspect.fb",GFX_TOP);inspected=1;}JSValue turn=JS_GetPropertyStr(ctx,view,"turn");int32_t n=0;JS_ToInt32(ctx,&n,turn);JS_FreeValue(ctx,turn);if(n>=3&&!boardCaptured){capture("native-board-top.fb",GFX_TOP);capture("native-board-bottom.fb",GFX_BOTTOM);boardCaptured=1;}}
